using System;
using System.IO;
using System.Text;
using System.Threading;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Web.Script.Serialization;
using Valve.VR;

// Optional companion. OpenVR work stays on this process's main thread.
public partial class OrbitVR {
 const int Width=1536, Height=960, CaptureWidth=1920, CaptureHeight=1200, MouseWidth=1024, MouseHeight=640, FrameBytes=CaptureWidth*CaptureHeight*4;
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 static readonly object Gate=new object(), Output=new object();
 static readonly AutoResetEvent Wake=new AutoResetEvent(false);
 static readonly Queue<Dictionary<string,object>> Commands=new Queue<Dictionary<string,object>>();
 static readonly Dictionary<int,byte[]> Pending=new Dictionary<int,byte[]>();
 static volatile bool quit; static bool fixture, visible, fixtureVisible=true; static string mode="dashboard";
 static ulong dashboard,thumbnail,panel; static CVRSystem system; 
 static void Emit(object value){lock(Output){Console.WriteLine(Json.Serialize(value));Console.Out.Flush();}}
 static string Text(Dictionary<string,object> row,string key){object v;return row.TryGetValue(key,out v)?Convert.ToString(v):"";}
 static double Number(Dictionary<string,object> row,string key,double fallback){object v;double n;return row.TryGetValue(key,out v)&&double.TryParse(Convert.ToString(v),out n)&&!double.IsNaN(n)&&!double.IsInfinity(n)?n:fallback;}
 static void Check(EVROverlayError e){if(e!=EVROverlayError.None)throw new Exception("SteamVR overlay: "+e);}
 static HmdMatrix34_t Identity(){return new HmdMatrix34_t{m0=1,m5=1,m10=1};}
 static byte[] Rgba(byte[] bgra){if(bgra.Length!=FrameBytes)throw new Exception("Invalid overlay frame.");var rgba=bgra;for(int n=0;n<rgba.Length;n+=4){byte b=rgba[n];rgba[n]=rgba[n+2];rgba[n+2]=b;}return rgba;}
 static void Input(){try{var reader=new BinaryReader(Console.OpenStandardInput());while(!quit){int length=reader.ReadInt32();if(length<1||length>FrameBytes+10)throw new Exception("Invalid packet size.");byte type=reader.ReadByte();if(type==1||type==2||type==3){int id=type==3?5:type==2?reader.ReadByte():0,offset=type==2?2:1,w=id==5?WatchWidth:id==0?Width:CaptureWidth,h=id==5?WatchHeight:id==0?Height:CaptureHeight,count=w*h*4;if((type==2&&(id<1||id>4))||length!=count+offset+8||reader.ReadInt32()!=w||reader.ReadInt32()!=h)throw new Exception("Invalid frame dimensions.");var frame=reader.ReadBytes(count);if(frame.Length!=count)break;lock(Gate){Pending[id]=frame;}Wake.Set();}else if(type==0&&length<16384){var bytes=reader.ReadBytes(length-1);if(bytes.Length!=length-1)break;var command=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(bytes));lock(Gate){if(Commands.Count>=32)throw new Exception("Too many overlay commands.");Commands.Enqueue(command);}Wake.Set();}else throw new Exception("Invalid packet type.");}}catch(EndOfStreamException){}catch(Exception e){Emit(new{type="error",message=e.Message});}finally{quit=true;Wake.Set();}}
 static void Configure(ulong handle){Check(OpenVR.Overlay.SetOverlayInputMethod(handle,VROverlayInputMethod.Mouse));var scale=new HmdVector2_t{v0=MouseWidth,v1=MouseHeight};Check(OpenVR.Overlay.SetOverlayMouseScale(handle,ref scale));Check(OpenVR.Overlay.SetOverlayFlag(handle,VROverlayFlags.SendVRSmoothScrollEvents,true));}
 static void SetMode(string next){if(!ValidAnchor(next,true))throw new Exception("Choose a panel position.");var config=next=="dashboard"?mainPlacement:DefaultPanel(0);config.anchor=next;if(next.StartsWith("wrist")){ShowWatch(next,watchWidth);config.width=watchWidth;if(!fixture)Check(OpenVR.Overlay.HideOverlay(panel));}else if(!fixture){if(next=="dashboard"){Check(OpenVR.Overlay.HideOverlay(panel));OpenVR.Overlay.ShowDashboard("io.github.tkokero.orbit.experimental");}else{Place(panel,config,true);Check(OpenVR.Overlay.ShowOverlay(panel));}}mainPlacement=config;mode=next;Emit(new{type="mode",mode=mode,placement=mainPlacement});}
 static int keyboardPanel; static string keyboardContext="search";
 static object Command(Dictionary<string,object> c){string type=Text(c,"type");if(type=="panel-focus")return FocusPanelCommand(c);if(type=="watch")return WatchCommand(c);if(type=="panels-visible")return PanelsVisible(c);if(type=="stop"){quit=true;return new{stopping=true};}if(type=="mode"){SetMode(Text(c,"mode"));return new{mode=mode};}if(type=="keyboard"){string text=Text(c,"text");if(text.Length>128)text=text.Substring(0,128);keyboardPanel=(int)Number(c,"panelId",0);keyboardContext=Text(c,"context");if(!fixture)Check(OpenVR.Overlay.ShowKeyboardForOverlay(keyboardPanel==0?(mode=="dashboard"?dashboard:panel):ExtraHandle(keyboardPanel),0,0,0,keyboardPanel==0?"Search Orbit":"Type into selected window",128,text,(ulong)keyboardPanel));else Emit(new{type="keyboard",text="DOOM",panelId=keyboardPanel,context=keyboardContext});return new{opened=true};}if(type=="panel-manipulate"||type=="panel-visible"||type=="panel-create"||type=="panel-update"||type=="panel-close"||type=="layout"||type=="hud"||type=="hud-theme"||type=="interaction")return PanelCommand(c);if(type=="room-read"||type=="room-apply"||type=="room-undo")return RoomCommand(c);if(type=="window-identity"||type=="window-input"||type=="media")return DesktopCommand(c);if(fixture&&type=="fixture-visibility"){fixtureVisible=Convert.ToBoolean(c["visible"]);return new{changed=true};}if(fixture&&type=="fixture-watch-gaze"){fixtureWatchLooking=Convert.ToBoolean(c["looking"]);WatchVisibility();return new{changed=true};}if(fixture&&type=="fixture-pointer"){Emit(new{type="pointer",panelId=(int)Number(c,"panelId",0),eventType=Text(c,"eventType")=="down"?"down":"click",device=(int)Number(c,"device",1),x=Math.Max(0,Math.Min(1023,(int)Number(c,"x",0))),y=Math.Max(0,Math.Min(639,(int)Number(c,"y",0)))});return new{sent=true};}if(type=="icon"){if(!fixture){string file=Text(c,"file");if(File.Exists(file))Check(OpenVR.Overlay.SetOverlayFromFile(thumbnail,file));}return new{set=true};}throw new Exception("Unknown VR command.");}
 static void Pointer(VREvent_t e,int id,string kind){Emit(new{type="pointer",panelId=id,eventType=kind,device=e.trackedDeviceIndex,x=(int)e.data.mouse.x,y=(id==5?WatchHeight:MouseHeight)-(int)e.data.mouse.y});}
 static void Events(ulong handle,int id){var e=new VREvent_t();var move=new VREvent_t();bool moving=false;int count=0;while(count++<256&&OpenVR.Overlay.PollNextOverlayEvent(handle,ref e,(uint)Marshal.SizeOf(typeof(VREvent_t)))){var type=(EVREventType)e.eventType;if(type==EVREventType.VREvent_MouseMove){move=e;moving=true;continue;}if(moving){Pointer(move,id,"move");moving=false;}if(type==EVREventType.VREvent_Quit){quit=true;return;}if(type==EVREventType.VREvent_MouseButtonDown||type==EVREventType.VREvent_MouseButtonUp){if(e.data.mouse.button!=(uint)EVRMouseButton.Left)continue;if(type==EVREventType.VREvent_MouseButtonUp&&grabPanel==id)EndGrab();else Pointer(e,id,type==EVREventType.VREvent_MouseButtonDown?"down":"click");}else if(type==EVREventType.VREvent_ScrollDiscrete||type==EVREventType.VREvent_ScrollSmooth)Emit(new{type="pointer",panelId=id,eventType="scroll",delta=-e.data.scroll.ydelta*120});else if(type==EVREventType.VREvent_KeyboardDone){var text=new StringBuilder(512);OpenVR.Overlay.GetKeyboardText(text,512);Emit(new{type="keyboard",text=text.ToString(),panelId=keyboardPanel,context=keyboardContext});}}if(moving)Pointer(move,id,"move");}
 static void InputEvents(){if(fixture)return;if(watchHandle!=0)Events(watchHandle,5);Events(dashboard,0);Events(panel,0);foreach(var p in extraPanels)Events(p.Value.handle,p.Key);var e=new VREvent_t();for(int n=0;n<32&&system.PollNextEvent(ref e,(uint)Marshal.SizeOf(typeof(VREvent_t)));n++)if((EVREventType)e.eventType==EVREventType.VREvent_Quit)quit=true;TickGrab();}
 static void SelfTest(){var bytes=new byte[FrameBytes];bytes[0]=10;bytes[1]=20;bytes[2]=30;bytes[3]=255;var result=Rgba(bytes);if(result[0]!=30||result[1]!=20||result[2]!=10||result[3]!=255)throw new Exception("Frame conversion failed.");TelemetryTests();RoomTests();WatchTests();ManipulationTests();Emit(new{type="selftest",passed=true,width=Width,height=Height,eventBytes=Marshal.SizeOf(typeof(VREvent_t)),nativeRuntime=false});}
 public static int Main(string[] args){Console.OutputEncoding=new UTF8Encoding(false);bool initialized=false;try{if(Array.IndexOf(args,"--texture-self-test")>=0){GraphicsTest();return 0;}if(Array.IndexOf(args,"--self-test")>=0){SelfTest();return 0;}fixture=Array.IndexOf(args,"--fixture")>=0;if(!fixture){var error=EVRInitError.None;system=OpenVR.Init(ref error,EVRApplicationType.VRApplication_Overlay);if(error!=EVRInitError.None||system==null)throw new Exception("SteamVR could not connect: "+error+". Start SteamVR and try again.");initialized=true;Check(OpenVR.Overlay.CreateDashboardOverlay("io.github.tkokero.orbit.experimental","Orbit",ref dashboard,ref thumbnail));Check(OpenVR.Overlay.CreateOverlay("io.github.tkokero.orbit.experimental.panel","Orbit panel",ref panel));Configure(dashboard);Configure(panel);Check(OpenVR.Overlay.SetOverlayWidthInMeters(dashboard,2.4f));Check(OpenVR.Overlay.SetOverlayWidthInMeters(panel,1.1f));InitGraphics(false);}var input=new Thread(Input);input.IsBackground=true;input.Start();Emit(new{type="ready",fixture=fixture});if(!fixture)OpenVR.Overlay.ShowDashboard("io.github.tkokero.orbit.experimental");while(!quit){InputEvents();Dictionary<string,object> command=null;Dictionary<int,byte[]> frames;lock(Gate){if(Commands.Count>0)command=Commands.Dequeue();frames=new Dictionary<int,byte[]>(Pending);Pending.Clear();}for(int batch=0;command!=null&&batch<8;batch++){string request=Text(command,"requestId");try{object value=Command(command);if(request!="")Emit(new{type="reply",requestId=request,data=value});}catch(Exception e){if(request!="")Emit(new{type="reply",requestId=request,error=e.Message});else Emit(new{type="error",message=e.Message});}if(batch<7)lock(Gate){command=Commands.Count>0?Commands.Dequeue():null;}}bool now=fixture?fixtureVisible:OpenVR.Overlay.IsOverlayVisible(dashboard)||OpenVR.Overlay.IsOverlayVisible(panel);if(now!=visible){visible=now;Emit(new{type="visibility",visible=visible});}foreach(var frame in frames){ulong handle=frame.Key==5?watchHandle:frame.Key==0?dashboard:ExtraHandle(frame.Key);bool show=fixture?(frame.Key==5?watchVisible:fixtureVisible):frame.Key==5?watchEnabled&&watchVisible:frame.Key==0?visible:handle!=0&&OpenVR.Overlay.IsOverlayVisible(handle);if(!show)continue;if(!fixture){if(frame.Key==5){SubmitTexture(watchHandle,frame.Value,WatchWidth,WatchHeight,true);if(watchVisible)Check(OpenVR.Overlay.ShowOverlay(watchHandle));}else if(frame.Key==0){if(OpenVR.Overlay.IsOverlayVisible(dashboard))SubmitTexture(dashboard,frame.Value,Width,Height,true);if(OpenVR.Overlay.IsOverlayVisible(panel))SubmitTexture(panel,frame.Value,Width,Height,true);}else SubmitTexture(handle,frame.Value,CaptureWidth,CaptureHeight,true);}Emit(new{type="frame",panelId=frame.Key,accepted=true});InputEvents();}WatchVisibility();TickWatchFocus();TickTools();bool workWaiting;lock(Gate){workWaiting=Commands.Count>0||Pending.Count>0;}Wake.WaitOne(workWaiting?0:visible||watchVisible||extraPanels.Count>0||hudEnabled?16:watchEnabled?33:150);}return 0;}catch(Exception e){Emit(new{type="fatal",message=e.Message});return 1;}finally{if(initialized){try{foreach(var p in extraPanels)OpenVR.Overlay.DestroyOverlay(p.Value.handle);if(hudHandle!=0)OpenVR.Overlay.DestroyOverlay(hudHandle);if(watchHandle!=0)OpenVR.Overlay.DestroyOverlay(watchHandle);if(panel!=0)OpenVR.Overlay.DestroyOverlay(panel);if(thumbnail!=0)OpenVR.Overlay.DestroyOverlay(thumbnail);if(dashboard!=0)OpenVR.Overlay.DestroyOverlay(dashboard);}catch{}OpenVR.Shutdown();}CloseGraphics();}}
}
